/** @brief Exact rational reference inputs, stored as IEEE binary64 bits.
 * For each finite candidate c, use exact Fractions a,b,s,c and n=floor((c-a)/s).
 * Select nearest among a+n*s, a+(n+1)*s (when <=b), and b; ties select higher.
 * Convert the selected exact rational once with nearest-even binary64 rounding.
 * Endpoint inputs retain endpoint bits. Seed 0x363; no runtime generator/dependency.
 */
struct NumericSnapReferenceCase {
  std::uint64_t minimumBits;   ///< Inclusive minimum.
  std::uint64_t maximumBits;   ///< Inclusive maximum.
  std::uint64_t stepBits;      ///< Positive valid step.
  std::uint64_t candidateBits; ///< Finite in-range pointer value.
  std::uint64_t expectedBits;  ///< Exact rational oracle rounded once.
};

